// === Validate input + apply UTMs + generate slug ===
// See n8n/lib/validate.js for the authoritative version.

let payload = $input.first().json.body;
if (typeof payload === 'string') {
  try { payload = JSON.parse(payload); }
  catch (e) { throw new Error(`Body is not valid JSON: ${e.message}`); }
}
if (!payload || typeof payload !== 'object') payload = $input.first().json;

const REQUIRED = ['mode', 'partner_name', 'color_primary', 'color_secondary', 'widget_url'];
const missing = REQUIRED.filter((f) => !payload[f]);
if (missing.length) throw new Error(`Missing required fields: ${missing.join(', ')}`);

if (!payload.logo_file_data && !payload.logo_file_url) throw new Error('Logo is required: provide logo_file_data (base64) or logo_file_url.');

const { mode, partner_name, color_primary, color_secondary, widget_url } = payload;

if (!['create', 'update'].includes(mode)) throw new Error(`Invalid mode '${mode}'.`);

const HEX = /^#[0-9A-F]{6}$/i;
if (!HEX.test(color_primary)) throw new Error(`Invalid color_primary '${color_primary}'.`);
if (!HEX.test(color_secondary)) throw new Error(`Invalid color_secondary '${color_secondary}'.`);

function toSlug(s) {
  return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

let slug;
if (mode === 'create') {
  slug = toSlug(partner_name);
  if (!slug) throw new Error(`Cannot derive slug from '${partner_name}'.`);
} else {
  if (!payload.slug) throw new Error("'update' mode requires slug.");
  slug = payload.slug;
  if (!/^[a-z0-9-]+$/.test(slug)) throw new Error(`Invalid slug '${slug}'.`);
}

const RESERVED = ['template', '_assets', '_test', 'n8n', 'example'];
if (mode === 'create' && RESERVED.includes(slug)) throw new Error(`Slug '${slug}' is reserved.`);

if (typeof widget_url !== 'string' || !/^https?:\/\/[^\s]+/i.test(widget_url)) {
  throw new Error(`Invalid widget_url. Value: ${JSON.stringify(widget_url)} (type: ${typeof widget_url}).`);
}
function appendQueryParams(base, params) {
  const pairs = [];
  for (const [k, v] of Object.entries(params)) {
    if (v && String(v).trim()) pairs.push(`${encodeURIComponent(k)}=${encodeURIComponent(String(v).trim())}`);
  }
  if (pairs.length === 0) return base;
  return base + (base.indexOf('?') === -1 ? '?' : '&') + pairs.join('&');
}
const widget_url_final = appendQueryParams(widget_url, { utm_source: payload.utm_source, utm_medium: payload.utm_medium, utm_campaign: payload.utm_campaign });

function extFromUrl(url, fallback) {
  if (!url || typeof url !== 'string') return fallback;
  const m = url.split('?')[0].split('#')[0].match(/\.([a-z0-9]+)$/i);
  return m ? m[1].toLowerCase() : fallback;
}

function extFromName(name, fb) { if (!name || typeof name !== 'string') return fb; const m = name.match(/\.([a-z0-9]+)$/i); return m ? m[1].toLowerCase() : fb; }

const has_logo_data = !!payload.logo_file_data;
const has_hero_data = !!payload.hero_file_data;
const has_hero_url = !!payload.hero_file_url;
const has_hero = has_hero_data || has_hero_url;

const logo_ext = has_logo_data ? extFromName(payload.logo_file_name, 'png') : extFromUrl(payload.logo_file_url, 'png');
const hero_ext = has_hero_data ? extFromName(payload.hero_file_name, 'jpg') : (has_hero_url ? extFromUrl(payload.hero_file_url, 'jpg') : null);

return [{
  json: {
    slug, mode, partner_name, color_primary, color_secondary,
    widget_url: widget_url_final,
    has_logo_data, has_hero, has_hero_data,
    logo_file_data: payload.logo_file_data || null,
    logo_file_url: payload.logo_file_url || null,
    hero_file_data: payload.hero_file_data || null,
    hero_file_url: payload.hero_file_url || null,
    logo_ext, hero_ext,
    logo_path: `./logo.${logo_ext}`,
    hero_image_path: has_hero ? `./hero.${hero_ext}` : '/_assets/hero-default.jpg',
    embed_widget: !!payload.embed_widget,
    cobrand: !!payload.cobrand,
    cta_href: payload.embed_widget ? '#apply' : widget_url_final,
    requester_slack_id: payload.requester_slack_id || null,
  }
}];

// === Process template: placeholder replace + IF blocks ===
// See n8n/lib/process.js for authoritative version.

const data = $('Validate').first().json;
const templateB64 = $('Read Template').first().json.content;
let html = Buffer.from(templateB64, 'base64').toString('utf-8');

const replacements = {
  PARTNER_NAME: data.partner_name,
  LOGO_PATH: data.logo_path || '',
  COLOR_PRIMARY: data.color_primary,
  COLOR_SECONDARY: data.color_secondary,
  WIDGET_URL: data.widget_url,
  HERO_IMAGE_PATH: data.hero_image_path,
  CTA_HREF: data.cta_href,
};

for (const [k, v] of Object.entries(replacements)) {
  html = html.split(`{{${k}}}`).join(v);
}

function processIf(html, flag, keep) {
  const s = `<!--IF:${flag}-->`;
  const e = `<!--/IF:${flag}-->`;
  if (keep) return html.split(s).join('').split(e).join('');
  const re = new RegExp(`<!--IF:${flag}-->[\\s\\S]*?<!--/IF:${flag}-->`, 'g');
  return html.replace(re, '');
}

const flags = {
  embed: data.embed_widget,
  loader: !data.embed_widget,
  cobrand: data.cobrand,
};
for (const [flag, keep] of Object.entries(flags)) {
  html = processIf(html, flag, keep);
}

const processed_html_b64 = Buffer.from(html, 'utf-8').toString('base64');
return [{ json: { ...data, processed_html: html, processed_html_b64 } }];

// === Build Vercel deploy payload from extracted zipball ===
// See n8n/lib/build-deploy.js for authoritative version.

const items = $input.all();
const EXCLUDE = [
  /^template\//,
  /^PLAN\.md$/,
  /^\.git\//,
  /^\.vercel\//,
  /^\.vercelignore$/,
  /^\.gitignore$/,
  /^n8n\//,
  /\/\.DS_Store$/,
  /^\.DS_Store$/,
];

const files = [];
for (const item of items) {
  const fileName = item.json.fileName || item.json.name || item.binary?.data?.fileName;
  if (!fileName) continue;
  const stripped = fileName.replace(/^[^/]+\//, '');
  if (!stripped || stripped.endsWith('/')) continue;
  if (EXCLUDE.some((re) => re.test(stripped))) continue;
  const data = item.binary?.data?.data;
  if (!data) continue;
  files.push({ file: stripped, data, encoding: 'base64' });
}

if (files.length === 0) throw new Error('No files to deploy.');

return [{ json: { files, file_count: files.length, slug: $('Validate').first().json.slug, partner_name: $('Validate').first().json.partner_name, requester_slack_id: $('Validate').first().json.requester_slack_id } }];
